#!/usr/bin/env bash
# Builds and deploys the vite.dev homepage migration to Vercel production: deploy/vite-dev/deploy.sh old|new|preview|front
# or to Cloudflare Workers: cf-old|cf-new|cf-preview (deploy/cloudflare.sh; the old site as mm-vite-dev-old, the port as mm-vite-dev-new).
# old:   the VitePress build of vitejs/vite's docs (DOCS, default ~/dev/scratch/vite/docs), static, as project vite-dev-old.
# new:   examples/vite-dev-markless (every page on Markless, generated by its scripts/import-docs.ts), built with the Vercel preset, as vite-dev-markless,
#        on the Markless scripts/link-markless.sh linked; the build output and the preview's caching are checked before the promote.
# preview: new without the promote; prints the checked preview URL.
# front: the vercel.json `markless-migrate config --vercel` writes (switched routes to the new app, the rest to the old one)
#        plus the check report at /_migrate/, as project migrate-demo (https://markless-migrate-demo.vercel.app).
set -euo pipefail
DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT="$DIR/../.."
APP="$ROOT/examples/vite-dev-markless"
DOCS="${DOCS:-$HOME/dev/scratch/vite/docs}"
SCOPE=jack-shelton
OLD_URL=https://vite-dev-old.vercel.app
NEW_URL=https://vite-dev-markless.vercel.app
# The caching plan (caching.json here, from cache plan) goes into the app before every build.
cache_apply() { mkdir -p .migrate && cp "$DIR/caching.json" .migrate/caching.json && node "$ROOT/src/cli.ts" cache apply; }
link() { [ -f "$1/.vercel/project.json" ] || (cd "$1" && vercel link --yes --project "$2" --scope "$SCOPE" >/dev/null && rm -f .env.local); }
case "${1:-}" in
	old)
		rm -rf "$DIR/old/public" && cp -R "$DOCS/.vitepress/dist" "$DIR/old/public" && rm -f "$DIR/old/public/_redirects" "$DIR/old/public/_headers"
		node "$DIR/old/vercel-config.mjs" "$DOCS/.vitepress/dist"
		link "$DIR/old" vite-dev-old
		(cd "$DIR/old" && vercel build --prod --yes && vercel deploy --prebuilt --prod --yes --scope "$SCOPE")
		;;
	new|preview)
		link "$APP" vite-dev-markless
		rm -rf "$APP/.vercel/output"
		(cd "$APP" && cache_apply && NITRO_PRESET=vercel npm run build)
		# A cached page or fragment URL without its ISR function runs the server function on every click: refuse before uploading.
		(cd "$APP" && node "$ROOT/src/cli.ts" cache output)
		URL=$(cd "$APP" && vercel deploy --prebuilt --yes --scope "$SCOPE" | grep -o "https://[^ ]*\.vercel\.app" | tail -1)
		BYPASS=$(vercel api "/v9/projects/vite-dev-markless?teamId=$SCOPE" 2>/dev/null | node -e 'const p=JSON.parse(require("fs").readFileSync(0,"utf8")).protectionBypass??{};process.stdout.write(Object.keys(p).find((k)=>p[k].scope==="automation-bypass")??"")')
		# The preview is promoted only when the CDN keeps its pages and their fragment URLs.
		(cd "$APP" && node "$ROOT/src/cli.ts" cache check --new "$URL" --no-psi --expiry-wait 0 ${BYPASS:+--header "x-vercel-protection-bypass:$BYPASS"} \
			--route / --route /guide/ --route /guide/features --route /config/build-options --route /blog/announcing-vite8)
		if [ "$1" = preview ]; then echo "$URL"; else vercel promote "$URL" --yes --scope "$SCOPE"; fi
		;;
	front)
		FRONT="$DIR/front"
		link "$FRONT" migrate-demo
		(cd "$FRONT" && vercel pull --yes --environment production --scope "$SCOPE" >/dev/null && rm -f .env.local .gitignore)
		rm -rf "$FRONT/public/_migrate/shots" && mkdir -p "$FRONT/public/_migrate/shots"
		cp "$APP/.migrate/report.html" "$APP/.migrate/report.json" "$FRONT/public/_migrate/"
		for shot in $(grep -o 'shots/[a-f0-9]*\.png' "$APP/.migrate/report.html" | sort -u); do cp "$APP/.migrate/$shot" "$FRONT/public/_migrate/$shot"; done
		(cd "$APP" && node "$ROOT/src/cli.ts" config --old "$OLD_URL" --new "$NEW_URL" --vercel "$FRONT/vercel.json" --new-build .vercel/output/static)
		(cd "$FRONT" && vercel build --prod --yes && vercel deploy --prebuilt --prod --yes --scope "$SCOPE")
		;;
	cf-old)
		# Cloudflare reads the Netlify _redirects and _headers VitePress writes; it rejects a rule from another host or with a
		# wildcard before a suffix (/*.txt, which only sends .txt to .md) and needs no self-rewrite.
		OLD="$(mktemp -d)/dist"
		cp -R "$DOCS/.vitepress/dist" "$OLD"
		grep -v -E '^https?://|^/\*\.|200!' "$DOCS/.vitepress/dist/_redirects" > "$OLD/_redirects"
		bash "$DIR/../cloudflare.sh" static "$OLD" mm-vite-dev-old
		;;
	cf-new|cf-preview)
		rm -rf "$APP/.output"
		(cd "$APP" && cache_apply && NITRO_PRESET=cloudflare-module npm run build)
		PREVIEW=$([ "$1" = cf-preview ] && echo 1 || true) bash "$DIR/../cloudflare.sh" port "$APP" mm-vite-dev-new \
			/ /guide/ /guide/features /config/build-options /blog/announcing-vite8
		;;
	*) echo "usage: $0 old|new|preview|front|cf-old|cf-new|cf-preview" >&2; exit 1 ;;
esac
